package net.officefloor.hq.app.access;

/** A setting on a sheet: its key and value (null: blank), and the from-date it was saved from when one was given (null otherwise). */
public record Setting(String sheetId, String key, String value, java.time.LocalDate from) {

    /** Whether the key's setting is dated: one that carries a figure (every key but the policy date, period numbering from and the permissions). */
    public static boolean isDated(String key) {
        return !POLICY_DATE.equals(key) && !PERIOD_NUMBERING_FROM.equals(key) && !isPermission(key);
    }

    /** Whether the key is one of the permission matrix's (perm-<action>). */
    public static boolean isPermission(String key) {
        return key.startsWith(PERMISSION) && PERMISSION_STANDING.containsKey(key.substring(PERMISSION.length()));
    }

    /** The value a dated key has before every from-date: the floor's, the terms' and the late percent's starting value; null (blank) for the rest. */
    public static String starting(String key) {
        return switch (key) {
            case FLOOR -> FLOOR_DEFAULT;
            case TERMS -> TERMS_DEFAULT;
            case LATE_PCT -> LATE_PCT_DEFAULT;
            default -> null;
        };
    }

    /** The most a clerk may settle a claim's due for; blank means no limit. */
    public static final String CLERK_LIMIT = "clerk-limit";

    /** The due above which a claim needs a proof before it is settled or approved; blank means none. */
    public static final String PROOF_THRESHOLD = "proof-threshold";

    /** The most a person's due-total may be; an amount with two decimals, blank for none. */
    public static final String CAP = "cap";

    /** The least a claim's live due may be; an amount with two decimals. */
    public static final String FLOOR = "floor";

    /** The floor a sheet starts with, until it is set. */
    public static final String FLOOR_DEFAULT = "1.00";

    /** The number of days after its date a claim is due by; a whole number. */
    public static final String TERMS = "terms";

    /** The terms a sheet starts with, until they are set. */
    public static final String TERMS_DEFAULT = "14";

    /** A grade's own terms (the key is this plus the grade, terms-A); blank means the sheet's terms. */
    public static final String TERMS_OF_GRADE = "terms-";

    /** The grades that may have their own terms. */
    public static final java.util.Set<String> GRADES = java.util.Set.of("A", "B", "C");

    /** The percent of its figure an overdue claim's due gains for every full 30 days it is overdue; two decimals. */
    public static final String LATE_PCT = "late-pct";

    /** The late percent a sheet starts with, until it is set. */
    public static final String LATE_PCT_DEFAULT = "0.00";

    /** The date before which a claim's live figures round half up, and from which half to even; blank means the sheet's today. */
    public static final String POLICY_DATE = "policy-date";

    /** The date from which (on the sheet's today) an opened claim is numbered within its period; blank means off. */
    public static final String PERIOD_NUMBERING_FROM = "period-numbering-from";

    /** The roles that may take an action (the key is this plus the action, perm-open): a comma separated list of roles, blank for the standing rule. */
    public static final String PERMISSION = "perm-";

    /** Each action's standing rule, the roles that may take it while its permission is blank. */
    public static final java.util.Map<String, java.util.List<String>> PERMISSION_STANDING = java.util.Map.of(
            "open", java.util.List.of(Role.CLERK, Role.STEWARD),
            "settle", java.util.List.of(Role.CLERK, Role.STEWARD),
            "void", java.util.List.of(Role.CLERK, Role.STEWARD),
            "close", java.util.List.of(Role.CLERK, Role.STEWARD),
            "reassign", java.util.List.of(Role.STEWARD),
            "reopen", java.util.List.of(Role.STEWARD));
}
package net.officefloor.hq.app.access;

import java.math.BigDecimal;
import java.util.regex.Pattern;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** A setting's fields: a known key, its value, and for a dated setting an optional from-date (yyyy-mm-dd). The terms are a whole number of days. A grade's terms (terms-<grade>) are a whole number of days, or blank for the sheet's terms. The floor is an amount with up to two decimals. The clerk limit is an amount with up to two decimals, or blank for no limit. The late percent is a number with up to two decimals. The policy date is a date (yyyy-mm-dd), or blank for the sheet's today. Period numbering from is a date, or blank for off. The cap is an amount with up to two decimals, or blank for none. The proof threshold is an amount with up to two decimals, or blank for none. A permission (perm-<action>) is a comma separated list of roles, or blank for the standing rule. */
public class ValidateSetting {

    private static final Pattern AMOUNT = Pattern.compile("\\d{1,10}(\\.\\d{1,2})?");
    private static final Pattern DAYS = Pattern.compile("\\d{1,5}");

    public void validate(@RequestBody SettingRequest request, Out<SettingInput> setting, Out<ChangedBy> changedBy)
            throws BadRequestException {
        ChangedBy by = ChangedBy.of(request == null ? null : request.by());
        String key = request == null || request.key() == null ? "" : request.key().trim();
        String text = request == null || request.value() == null ? "" : request.value().trim();
        String fromText = request == null || request.from() == null ? "" : request.from().trim();
        java.time.LocalDate from = null;
        if (!fromText.isEmpty()) {
            if (!Setting.isDated(key)) {
                throw new BadRequestException("The " + key + " setting is not dated; leave its from-date blank");
            }
            try {
                from = java.time.LocalDate.parse(fromText);
            } catch (java.time.format.DateTimeParseException e) {
                throw new BadRequestException("A from-date is a date (yyyy-mm-dd), or blank for the sheet's today");
            }
        }
        if (Setting.TERMS.equals(key)) {
            if (!DAYS.matcher(text).matches()) {
                throw new BadRequestException("Terms are a whole number of days");
            }
            setting.set(new SettingInput(key, String.valueOf(Integer.parseInt(text)), from));
            changedBy.set(by);
            return;
        }
        if (key.startsWith(Setting.TERMS_OF_GRADE) && Setting.GRADES.contains(key.substring(Setting.TERMS_OF_GRADE.length()))) {
            if (!text.isEmpty() && !DAYS.matcher(text).matches()) {
                throw new BadRequestException("A grade's terms are a whole number of days, or blank for the sheet's terms");
            }
            setting.set(new SettingInput(key, text.isEmpty() ? null : String.valueOf(Integer.parseInt(text)), from));
            changedBy.set(by);
            return;
        }
        if (Setting.FLOOR.equals(key)) {
            if (!AMOUNT.matcher(text).matches()) {
                throw new BadRequestException("A floor is an amount with up to two decimals");
            }
            setting.set(new SettingInput(key, new BigDecimal(text).setScale(2).toPlainString(), from));
            changedBy.set(by);
            return;
        }
        if (Setting.LATE_PCT.equals(key)) {
            if (!AMOUNT.matcher(text).matches()) {
                throw new BadRequestException("A late percent is a number with up to two decimals");
            }
            setting.set(new SettingInput(key, new BigDecimal(text).setScale(2).toPlainString(), from));
            changedBy.set(by);
            return;
        }
        if (Setting.POLICY_DATE.equals(key)) {
            String date = null;
            if (!text.isEmpty()) {
                try {
                    date = java.time.LocalDate.parse(text).toString();
                } catch (java.time.format.DateTimeParseException e) {
                    throw new BadRequestException("A policy date is a date (yyyy-mm-dd), or blank for the sheet's today");
                }
            }
            setting.set(new SettingInput(key, date, from));
            changedBy.set(by);
            return;
        }
        if (Setting.PERIOD_NUMBERING_FROM.equals(key)) {
            String date = null;
            if (!text.isEmpty()) {
                try {
                    date = java.time.LocalDate.parse(text).toString();
                } catch (java.time.format.DateTimeParseException e) {
                    throw new BadRequestException("Period numbering from is a date (yyyy-mm-dd), or blank for off");
                }
            }
            setting.set(new SettingInput(key, date, from));
            changedBy.set(by);
            return;
        }
        if (Setting.CAP.equals(key)) {
            String value = null;
            if (!text.isEmpty()) {
                if (!AMOUNT.matcher(text).matches()) {
                    throw new BadRequestException("A cap is an amount with up to two decimals, or blank for none");
                }
                value = new BigDecimal(text).setScale(2).toPlainString();
            }
            setting.set(new SettingInput(key, value, from));
            changedBy.set(by);
            return;
        }
        if (Setting.PROOF_THRESHOLD.equals(key)) {
            String value = null;
            if (!text.isEmpty()) {
                if (!AMOUNT.matcher(text).matches()) {
                    throw new BadRequestException("A proof threshold is an amount with up to two decimals, or blank for none");
                }
                value = new BigDecimal(text).setScale(2).toPlainString();
            }
            setting.set(new SettingInput(key, value, from));
            changedBy.set(by);
            return;
        }
        if (Setting.isPermission(key)) {
            String value = null;
            if (!text.isEmpty()) {
                java.util.List<String> roles = java.util.Arrays.stream(text.split(",", -1)).map(String::trim).toList();
                if (roles.stream().anyMatch(r -> !r.equals(Role.CLERK) && !r.equals(Role.STEWARD))) {
                    throw new BadRequestException("A permission is a comma separated list of roles (clerk, steward), or blank for the standing rule");
                }
                value = String.join(",", roles);
            }
            setting.set(new SettingInput(key, value, from));
            changedBy.set(by);
            return;
        }
        if (!Setting.CLERK_LIMIT.equals(key)) {
            throw new BadRequestException("No such setting: " + key);
        }
        String value = null;
